import { createClient } from 'https://esm.sh/@supabase/supabase-js@2';
import { r2PublicUrl } from '../_shared/r2.ts';

type JsonRecord = Record<string, unknown>;

const MAX_BODY_BYTES = 16_000;
const DEFAULT_ALLOWED_ORIGINS = [
  'http://10.0.2.189:3000',
  'http://localhost:3000',
  'http://127.0.0.1:3000',
];

function isLocalOrigin(origin: string) {
  return /^https?:\/\/(localhost|127\.0\.0\.1|10\.\d+\.\d+\.\d+|192\.168\.\d+\.\d+|172\.(1[6-9]|2\d|3[01])\.\d+\.\d+)(:\d+)?$/.test(origin);
}

function configuredOrigins() {
  const envOrigins = (Deno.env.get('ALLOWED_ORIGINS') || '')
    .split(',')
    .map((origin) => origin.trim())
    .filter(Boolean);
  return [...DEFAULT_ALLOWED_ORIGINS, ...envOrigins];
}

function isAllowedOrigin(origin: string | null): boolean {
  if (!origin) return true;
  if (isLocalOrigin(origin)) return true;
  return configuredOrigins().includes(origin);
}

function corsHeaders(origin: string | null) {
  const allowed = origin && isAllowedOrigin(origin) ? origin : '*';
  return {
    'access-control-allow-origin': allowed,
    'access-control-allow-headers': 'authorization, x-client-info, apikey, content-type',
    'access-control-allow-methods': 'POST, OPTIONS',
    'access-control-max-age': '86400',
    'cache-control': 'no-store',
    'x-content-type-options': 'nosniff',
    vary: 'Origin',
  };
}

function json(status: number, body: JsonRecord, origin: string | null, extraHeaders: HeadersInit = {}) {
  return new Response(JSON.stringify(body), {
    status,
    headers: { 'content-type': 'application/json; charset=utf-8', ...corsHeaders(origin), ...extraHeaders },
  });
}

async function digest(value: string) {
  const bytes = new TextEncoder().encode(value);
  const hash = await crypto.subtle.digest('SHA-256', bytes);
  return Array.from(new Uint8Array(hash)).map((byte) => byte.toString(16).padStart(2, '0')).join('');
}

function cleanIdentifier(value: unknown, max = 160) {
  const normalized = String(value || '').trim();
  if (!normalized || normalized.length > max || !/^[a-zA-Z0-9._:-]+$/.test(normalized)) return null;
  return normalized;
}

function clientIp(request: Request) {
  return request.headers.get('cf-connecting-ip')
    || request.headers.get('x-real-ip')
    || request.headers.get('x-forwarded-for')?.split(',')[0]?.trim()
    || 'unknown';
}

async function readJsonWithinLimit(request: Request): Promise<JsonRecord> {
  if (!request.body) throw new SyntaxError('invalid_json');
  const reader = request.body.getReader();
  const decoder = new TextDecoder();
  let size = 0;
  let text = '';
  try {
    while (true) {
      const { done, value } = await reader.read();
      if (done) break;
      size += value.byteLength;
      if (size > MAX_BODY_BYTES) throw new RangeError('payload_too_large');
      text += decoder.decode(value, { stream: true });
    }
    text += decoder.decode();
    const parsed = JSON.parse(text);
    if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) throw new SyntaxError('invalid_json');
    return parsed as JsonRecord;
  } finally {
    reader.releaseLock();
  }
}

async function checkRateLimit(
  admin: any,
  bucketKey: string,
  limit: number,
  windowSeconds: number,
  blockSeconds: number,
) {
  const { data, error } = await admin.rpc('gsa_auth_rate_limit_check', {
    p_bucket_key: bucketKey,
    p_limit: limit,
    p_window_seconds: windowSeconds,
    p_block_seconds: blockSeconds,
  });
  if (error || typeof data?.allowed !== 'boolean') throw new Error('rate_limit_unavailable');
  return data as { allowed: boolean; retry_after?: number };
}

export function normalizeServePayload(input: unknown) {
  if (!input || typeof input !== 'object') return null;
  const source = input as JsonRecord;
  const placement = cleanIdentifier(source.placement_code, 80);
  const viewer = cleanIdentifier(source.viewer_id, 160);
  const session = cleanIdentifier(source.session_id, 160);
  const route = String(source.route || '').trim().slice(0, 500);
  const device = String(source.device || '').trim().slice(0, 20);
  if (!placement || !viewer || !session || !['desktop', 'tablet', 'mobile'].includes(device)) return null;
  return { placement, viewer, session, route, device };
}

export async function handleRequest(request: Request) {
  const origin = request.headers.get('origin');
  if (request.method === 'OPTIONS') return new Response(null, { status: 204, headers: corsHeaders(origin) });
  if (origin && !isAllowedOrigin(origin)) return json(403, { error: 'origin_not_allowed' }, origin);
  if (request.method !== 'POST') return json(405, { error: 'method_not_allowed' }, origin, { allow: 'POST, OPTIONS' });

  const declaredLength = Number(request.headers.get('content-length') || 0);
  if (declaredLength > MAX_BODY_BYTES) return json(413, { error: 'payload_too_large' }, origin);

  let body: JsonRecord;
  try {
    body = await readJsonWithinLimit(request);
  } catch (error) {
    return json(
      error instanceof RangeError ? 413 : 400,
      { error: error instanceof RangeError ? 'payload_too_large' : 'invalid_json' },
      origin,
    );
  }

  const action = String(body.action || '').trim();

  const supabaseUrl = Deno.env.get('SUPABASE_URL') || '';
  const serviceRoleKey = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') || '';
  const admin = createClient(supabaseUrl, serviceRoleKey, {
    auth: { persistSession: false, autoRefreshToken: false },
  });

  if (action === 'serve') {
    const p = normalizeServePayload(body);
    if (!p) return json(400, { error: 'invalid_payload' }, origin);

    const { data, error } = await admin.rpc('gsa_ads_serve', {
      p_placement: p.placement,
      p_viewer_id: p.viewer,
      p_session_id: p.session,
      p_route: p.route,
      p_device: p.device,
    });

    if (error || !data?.ad) return json(404, { error: 'no_ad_available' }, origin);

    return json(200, {
      success: true,
      ad: {
        ...data.ad,
        creative_url: r2PublicUrl('private/ad-creatives/' + data.ad.storage_path)
      }
    }, origin);
  }

  if (action === 'event') {
    const token = cleanIdentifier(body.event_token, 60);
    const eventType = String(body.event_type || '').trim();
    if (!token || !['viewable', 'click', 'video_start', 'video_complete'].includes(eventType)) {
      return json(400, { error: 'invalid_event' }, origin);
    }
    const { data, error } = await admin.rpc('gsa_ads_record_event', {
      p_event_token: token,
      p_event_type: eventType,
    });
    if (error) return json(404, { error: 'event_not_found' }, origin);
    return json(200, { success: true, recorded: Boolean(data?.recorded) }, origin);
  }

  return json(400, { error: 'invalid_action' }, origin);
}

if (import.meta.main) Deno.serve(handleRequest);

﻿/**
 * r2.ts — Módulo compartilhado para acesso ao Cloudflare R2 via API S3
 * Usado pelas Edge Functions do Supabase para upload/download/delete de arquivos.
 *
 * Requer as variáveis de ambiente (Supabase Secrets):
 *   R2_ACCOUNT_ID   — ID da conta Cloudflare
 *   R2_ACCESS_KEY_ID — Access Key ID do R2 API Token
 *   R2_SECRET_ACCESS_KEY — Secret Access Key do R2 API Token
 *   R2_BUCKET_NAME  — Nome do bucket (gsa-hub-storage)
 *   R2_PUBLIC_URL   — URL pública do bucket R2
 */

export const R2_BUCKET = Deno.env.get('R2_BUCKET_NAME') ?? 'gsa-hub-storage';
export const R2_PUBLIC_URL = Deno.env.get('R2_PUBLIC_URL') ?? 'https://pub-7f7b1419c83c407ba9bcf6512329e79a.r2.dev';

const R2_ACCOUNT_ID = () => Deno.env.get('R2_ACCOUNT_ID') ?? '';
const R2_ACCESS_KEY = () => Deno.env.get('R2_ACCESS_KEY_ID') ?? '';
const R2_SECRET_KEY = () => Deno.env.get('R2_SECRET_ACCESS_KEY') ?? '';

function getEndpoint() {
  return `https://${R2_ACCOUNT_ID()}.r2.cloudflarestorage.com`;
}

// ─── AWS Signature V4 ─────────────────────────────────────────────────────────
async function hmac(key: ArrayBuffer | Uint8Array, data: string): Promise<ArrayBuffer> {
  const k = await crypto.subtle.importKey('raw', key, { name: 'HMAC', hash: 'SHA-256' }, false, ['sign']);
  return crypto.subtle.sign('HMAC', k, new TextEncoder().encode(data));
}

async function sha256hex(data: string | Uint8Array): Promise<string> {
  const buf = typeof data === 'string' ? new TextEncoder().encode(data) : data;
  const hash = await crypto.subtle.digest('SHA-256', buf);
  return Array.from(new Uint8Array(hash)).map(b => b.toString(16).padStart(2, '0')).join('');
}

async function signRequest(
  method: string,
  key: string,
  body: Uint8Array | null,
  contentType?: string,
): Promise<Record<string, string>> {
  const endpoint = getEndpoint();
  const region = 'auto';
  const service = 's3';
  const now = new Date();
  const date = now.toISOString().slice(0, 10).replace(/-/g, '');
  const datetime = now.toISOString().replace(/[-:]/g, '').slice(0, 15) + 'Z';
  const host = new URL(endpoint).host;

  const payloadHash = body ? await sha256hex(body) : 'e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855';
  const signedHeaders = contentType
    ? 'content-type;host;x-amz-content-sha256;x-amz-date'
    : 'host;x-amz-content-sha256;x-amz-date';

  const canonicalHeaders = contentType
    ? `content-type:${contentType}\nhost:${host}\nx-amz-content-sha256:${payloadHash}\nx-amz-date:${datetime}\n`
    : `host:${host}\nx-amz-content-sha256:${payloadHash}\nx-amz-date:${datetime}\n`;

  const canonicalPath = `/${R2_BUCKET}/${key.replace(/^\/+/, '')}`;
  const canonicalRequest = [method, canonicalPath, '', canonicalHeaders, signedHeaders, payloadHash].join('\n');

  const credentialScope = `${date}/${region}/${service}/aws4_request`;
  const stringToSign = ['AWS4-HMAC-SHA256', datetime, credentialScope, await sha256hex(canonicalRequest)].join('\n');

  const enc = new TextEncoder();
  const kDate = await hmac(enc.encode(`AWS4${R2_SECRET_KEY()}`), date);
  const kRegion = await hmac(kDate, region);
  const kService = await hmac(kRegion, service);
  const kSigning = await hmac(kService, 'aws4_request');
  const signatureBytes = await hmac(kSigning, stringToSign);
  const signature = Array.from(new Uint8Array(signatureBytes)).map(b => b.toString(16).padStart(2, '0')).join('');

  const authHeader = `AWS4-HMAC-SHA256 Credential=${R2_ACCESS_KEY()}/${credentialScope}, SignedHeaders=${signedHeaders}, Signature=${signature}`;

  return {
    Authorization: authHeader,
    'x-amz-date': datetime,
    'x-amz-content-sha256': payloadHash,
    ...(contentType ? { 'Content-Type': contentType } : {}),
  };
}

// ─── Upload de arquivo ────────────────────────────────────────────────────────
export async function r2Upload(
  key: string,
  body: Uint8Array,
  contentType: string,
): Promise<{ publicUrl: string; path: string }> {
  const normalizedKey = key.replace(/^\/+/, '');
  const headers = await signRequest('PUT', normalizedKey, body, contentType);

  const resp = await fetch(`${getEndpoint()}/${R2_BUCKET}/${normalizedKey}`, {
    method: 'PUT',
    headers,
    body,
  });

  if (!resp.ok) {
    const text = await resp.text();
    throw new Error(`R2 upload falhou [${resp.status}]: ${text}`);
  }

  return {
    publicUrl: `${R2_PUBLIC_URL}/${normalizedKey}`,
    path: normalizedKey,
  };
}

// ─── Download de arquivo ──────────────────────────────────────────────────────
export async function r2Download(key: string): Promise<{ body: Uint8Array; contentType: string }> {
  const normalizedKey = key.replace(/^\/+/, '');
  const headers = await signRequest('GET', normalizedKey, null);

  const resp = await fetch(`${getEndpoint()}/${R2_BUCKET}/${normalizedKey}`, { headers });
  if (!resp.ok) throw new Error(`R2 download falhou [${resp.status}]`);

  const body = new Uint8Array(await resp.arrayBuffer());
  const contentType = resp.headers.get('content-type') ?? 'application/octet-stream';
  return { body, contentType };
}

// ─── Delete de arquivo(s) ────────────────────────────────────────────────────
export async function r2Delete(keys: string[]): Promise<void> {
  await Promise.all(
    keys.map(async (key) => {
      const normalizedKey = key.replace(/^\/+/, '');
      const headers = await signRequest('DELETE', normalizedKey, null);
      const resp = await fetch(`${getEndpoint()}/${R2_BUCKET}/${normalizedKey}`, { method: 'DELETE', headers });
      if (!resp.ok && resp.status !== 404) {
        throw new Error(`R2 delete falhou [${resp.status}]: ${key}`);
      }
    }),
  );
}

// ─── URL pública ──────────────────────────────────────────────────────────────
export function r2PublicUrl(key: string): string {
  return `${R2_PUBLIC_URL}/${key.replace(/^\/+/, '')}`;
}

// ─── Mapeamento de bucket antigo → prefixo R2 ────────────────────────────────
export const BUCKET_PREFIX: Record<string, string> = {
  'classificados-midias':     'public/classified-media',
  'gsa-store-images':         'public/store-images',
  'gsa-site-campaigns':       'public/site-campaigns',
  'gsa-partner-applications': 'public/partner-applications',
  'gsa-ad-creatives':         'private/ad-creatives',
  'gsa-private-documents':    'private/documents',
  'documentos_cliente':       'private/client-docs',
  'documentos_prestador':     'private/provider-docs',
  'entregas_demandas':        'private/demand-deliveries',
  'emprestimos':              'private/loans',
  'whatsapp':                 'public/whatsapp',
  'product-imports':          'private/product-imports',
};
